def icon(kind):
 paths={'Explore':'<circle cx="12" cy="12" r="8"/><path d="m15 9-2 4-4 2 2-4Z"/>','Wallet':'<rect x="3" y="5" width="18" height="15" rx="4"/><path d="M16 10h5v5h-5z"/>','Activity':'<path d="M3 13h4l3-7 4 12 3-5h4"/>','Profile':'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-9 16-9 16 0"/>'}
 return '<svg class="icon" viewBox="0 0 24 24">'+paths[kind]+'</svg>'
def nav(active='Explore'):return '<nav data-system>'+''.join('<span class="'+('sel' if k==active else '')+'">'+icon(k)+k+'</span>' for k in ['Explore','Wallet','Activity','Profile'])+'</nav>'
focus='''<svg class="focus" viewBox="0 0 156 128" fill="none" aria-hidden="true"><path d="M35 16H20q-8 0-8 8v16M121 16h15q8 0 8 8v16M12 88v16q0 8 8 8h15M144 88v16q0 8-8 8h-15" stroke="currentColor" stroke-width="2" opacity=".35"/><rect x="35" y="32" width="86" height="64" rx="14" fill="currentColor" opacity=".07"/><path d="M55 49h34M55 60h24" stroke="currentColor" stroke-width="3" stroke-linecap="round" opacity=".4"/><circle cx="108" cy="84" r="20" fill="var(--accent)"/><path d="m108 76 0 16m-8-8h16" stroke="var(--on-accent)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>'''
def core(cls=''):
 return '<div class="app"><header><h1>Explore</h1><button>Post</button></header><div class="search">Search bounties</div><div class="segment"><button class="active">Online</button><button>Nearby</button></div><div class="controls"><span class="meta">0 bounties · Online</span><button class="quiet">Filters &amp; sort</button></div><div class="empty browse-empty" data-scrolls>'+focus+'<h2>No online bounties yet</h2><p>Post a task for someone to complete from anywhere.</p><button>Post a bounty</button></div>'+nav()+'</div>'
def screen(name,html,cls='',attrs=''):return f'<section class="screen {cls}" data-name="{name}" data-theme="dark" data-chrome="{'none' if name == 'signature' else 'dark' if cls in ('light','signal') else 'light'}" {attrs}>{html}</section>'
