 (p/name).write_text(f'<!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="{skill.as_uri()}/assets/device.css"><link rel="stylesheet" href="study.css"></head><body>{html}<script src="{skill.as_uri()}/assets/device.js"></script></body></html>')
