wallet='<div class="app"><header><h1>Wallet</h1></header><span class="meta">BraveScout1056 · 6sTy…Rtg</span><div class="hero"><span class="meta">Available · Test mode</span><div class="amount">18 <small>USDC</small></div><p>Available balance, excluding escrow.</p></div><div style="display:flex;gap:12px"><button style="flex:1">Receive</button><button class="ghost" style="flex:1">Explorer</button></div><div class="scroll" data-scrolls><h2>Tokens</h2><div class="line"><img class="token" src="file:///Users/Apple/Documents/ChatGPT/scoutvy/assets/images/tokens/usdc.png"><div class="copy"><strong>USDC</strong><p>USD Coin</p></div><strong>18</strong></div><div class="line"><img class="token" src="file:///Users/Apple/Documents/ChatGPT/scoutvy/assets/images/tokens/skr.png"><div class="copy"><strong>Seeker</strong><p>SKR</p></div><strong>0</strong></div><div class="section">SOL balance</div><p>9.958400242 SOL</p></div>'+nav('Wallet')+'</div>'
