post='<div class="app"><header><span class="back">‹</span><span class="inline-title">Post a bounty</span><span class="meta">1 of 5</span></header><div class="scroll" data-scrolls><h1>What do you need?</h1><p style="margin:12px 0 32px">Set the task and what counts as complete.</p><label>Title</label><div class="field">Give your bounty a clear title</div><label>Requirements</label><div class="field" style="min-height:136px">Describe what needs to be done and how you’ll review it.</div><label>Where can it be done?</label><div class="segment" style="margin-top:12px"><button class="active">Online</button><button>At a location</button></div><p class="section">What should be submitted?</p><div class="field" style="color:var(--ink)">Written response or work link</div></div><div class="footer" data-float><button style="opacity:.5">Choose reward</button></div></div>'
profile='<div class="app"><h1>Profile</h1><div class="hero"><h2>BraveScout1056</h2><span class="meta">6sTy…Rtg · Scout</span></div><div class="scroll" data-scrolls>'+''.join(('<div class="section">Preferences</div>' if x=='Notifications' else '<div class="section">Account</div>' if x=='Help' else '')+'<div class="line"><strong class="copy">'+x+'</strong><span>›</span></div>' for x in ['Username','My bounties','Seeker verification','Notifications','Permissions','Blocked users','Help','Your data','Sign out'])+'</div>'+nav('Profile')+'</div>'
intro='<div class="app"><header><span class="meta">scoutvy</span><button class="quiet">Skip</button></header><div class="empty onboard"><img class="hero-art" src="'+(root/'design/onboarding-preview/art/brief.svg').as_uri()+'"><h1>Your task.<br>Your terms.</h1><p>Set the requirements.<br>Choose what counts as complete.</p></div><div class="footer" data-float><button>Continue</button><p class="meta" style="text-align:center">Test mode · No real-money rewards</p></div></div>'
